import {VIDEO,CHAPTERS,DESMOS_TIPS} from './desmos-content.js?v=9';
import {matchDesmosTips,searchDesmosTips} from './desmos-matching.js?v=9';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const time=s=>Math.floor(s/60)+':'+String(s%60).padStart(2,'0');
const link=(url,label)=>`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)}</a>`;
export const DESMOS_URL='https://www.desmos.com/testing/collegeboard';
export function desmosQuestionButton(q){return q?.section==='Math'?`<button class="secondary desmos-trigger" data-action="desmos-question" data-id="${esc(q.id)}">Desmos tips</button>`:'';}
export function createDesmosGuide({getData,getQuestionText=()=>'',onUse,openTool}){
 let filters={query:'',chapter:'all',skill:'all'},question=null,questionMode=false,modalOpen=false;
 const byId=id=>getData().questions.find(q=>q.id===id);
 function tipMarkup(t,reason=''){
  const chapter=CHAPTERS.find(c=>c.id===t.chapterId);
  return `<details class="desmos-tip" data-tip-id="${t.id}"><summary data-action="desmos-use-tip" data-id="${t.id}"><span><strong>${esc(t.title)}</strong><small>${esc(chapter?.title||'Desmos')} · ${time(t.seconds)}${reason?' · '+esc(reason):''}</small></span></summary><div class="desmos-tip-body"><p class="desmos-recognition">${esc(t.recognition)}</p><ol>${t.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol><section class="desmos-example"><h3>Original example</h3><pre><code>${t.example.lines.map(esc).join('\n')}</code></pre><p>${esc(t.example.result)}</p></section><p class="desmos-caution"><strong>Check:</strong> ${esc(t.caution)}</p><div class="desmos-tip-links">${link(VIDEO.url+'&t='+t.seconds+'s','Watch at '+time(t.seconds))} ${link(DESMOS_URL,'Open SAT Desmos')}<details><summary>Documentation</summary>${t.docs.map((u,i)=>link(u,'Official reference '+(i+1))).join(' ')}</details></div></div></details>`;
 }
 function form(prefix){return `<div class="desmos-filters"><label>Search methods<input type="search" id="${prefix}-search" placeholder="intercepts, percentages, regression…" value="${esc(filters.query)}"></label><label>Chapter<select id="${prefix}-chapter"><option value="all">All chapters</option>${CHAPTERS.map(c=>`<option value="${c.id}" ${filters.chapter===c.id?'selected':''}>${esc(c.title)}</option>`).join('')}</select></label><label>Skill<select id="${prefix}-skill"><option value="all">All Math skills</option>${[...new Set(DESMOS_TIPS.flatMap(t=>t.skills))].sort().map(s=>`<option ${filters.skill===s?'selected':''}>${esc(s)}</option>`).join('')}</select></label></div>`;}
 function list(){
  if(questionMode&&question){const m=matchDesmosTips(question);return `<p class="small muted">${m.hasText?'Suggestions use the question’s wording and skill.':'Only the skill label is available for matching.'} Check each method’s conditions; these are reference tips, not verified solutions to this question.</p>${m.suggested.length?'<h3 class="desmos-group-title">Suggested methods</h3>'+m.suggested.map(x=>tipMarkup(x.tip,x.reason)).join(''):''}${m.related.length?'<h3 class="desmos-group-title">Methods for this skill</h3>'+m.related.map(x=>tipMarkup(x.tip,x.reason)).join(''):''}${!m.suggested.length&&!m.related.length?'<p>No specific method is matched. Use the library to find a technique, or solve this question algebraically.</p>':''}`;}
  const tips=searchDesmosTips(filters);return `<p class="small muted">${tips.length} of ${DESMOS_TIPS.length} methods</p>${tips.map(t=>tipMarkup(t)).join('')||'<p>No methods match. Try another word or clear the filters.</p>'}`;
 }
 function intro(){return `<p class="desmos-intro">Choose a method, check its conditions, then read the exact quantity the question asks for. These techniques use the SAT Desmos calculator; the site’s small local graph tool does not support regressions.</p><p class="small muted">Original study notes covering all ten instructional chapters of ${link(VIDEO.url,VIDEO.title)} by ${esc(VIDEO.creator)}. The full ${time(VIDEO.durationSeconds)} auto-caption transcript was reviewed on ${esc(VIDEO.reviewedOn)}. Mathematical cautions and original examples are added here.</p>`;}
 function library(){question=null;questionMode=false;modalOpen=false;return `<div class="page-title"><div><h1>Desmos tips</h1><p>Find the right calculator method for a Math question.</p></div></div><div class="desmos-library"><div class="summary-actions">${link(DESMOS_URL,'Open SAT Desmos')} ${link(VIDEO.url,'Watch the full guide')}<a href="#challenge">Seven-day practice</a></div>${intro()}${form('desmos')}<div id="desmos-tip-list">${list()}</div><details class="desmos-source-notes"><summary>Source notes and corrections</summary><p>The creator notes that both B and D work in the example at 9:17. That example is not reproduced as a single-answer question here. A square or absolute value can have zero, one, or more real solutions depending on the equation; finite samples and fitted parameters are not a proof. Decimal responses follow College Board directions, not a guarantee based on filling the field.</p><p>Tips are authored study material. Only questions verified in the PDF bank are labeled official. No video transcript or question examples from the creator are bundled.</p></details></div>`;}
 function openQuestion(q){if(q?.section!=='Math')return;question={...q,mathText:q.mathText||getQuestionText(q.id)};questionMode=true;modalOpen=true;filters={query:'',chapter:'all',skill:'all'};openTool('Desmos tips',`<div class="desmos-library desmos-question-panel"><p><strong>${esc(q.skill)}</strong><br><small>${esc(q.file)} · p. ${q.page} · Q ${esc(q.number)} · ID ${esc(q.id)}</small></p><p id="desmos-assistance" class="desmos-assistance">Opening a method during an unanswered practice question records it as help. Previewing this list alone does not count as a hint.</p><div class="desmos-panel-tabs"><button class="secondary" data-action="desmos-suggested">For this question</button><button class="secondary" data-action="desmos-browse">Search all methods</button>${link(DESMOS_URL,'Open SAT Desmos')}</div><div id="desmos-modal-filters" hidden>${form('desmos-modal')}</div><div id="desmos-tip-list">${list()}</div></div>`);}
 function refresh(){const el=document.getElementById('desmos-tip-list');if(el)el.innerHTML=list();}
 function click(action,target){
  if(action==='desmos-skill'){filters={query:'',chapter:'all',skill:target.dataset.skill||'all'};location.hash='desmos';return true;}
  if(action==='desmos-question'){openQuestion(byId(target.dataset.id));return true;}
  if(action==='desmos-use-tip'){const t=DESMOS_TIPS.find(t=>t.id===target.dataset.id),details=target.closest('details');if(t&&modalOpen&&question&&!details?.open){const counted=onUse(question.id,t.id);if(counted){const note=document.getElementById('desmos-assistance');if(note)note.textContent='This method is recorded as help for this attempt. Your setup and answer will still be checked separately.';}}return true;}
  if(action==='desmos-browse'||action==='desmos-suggested'){questionMode=action==='desmos-suggested';document.getElementById('desmos-modal-filters').hidden=questionMode;refresh();return true;}
  return false;
 }
 function input(event){const id=event.target.id,match=/^desmos(?:-modal)?-(search|chapter|skill)$/.exec(id);if(!match)return false;filters[match[1]==='search'?'query':match[1]]=event.target.value;questionMode=false;refresh();return true;}
 return {render:library,openQuestion,click,input};
}
